using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using FireSafety;
public static class TestSchoolExplore {public static async Task<string> Run(){var s=TrainingSession.Instance;var p=s.player;var cc=p.GetComponent<CharacterController>();var checks=new List<object>();var oldK=Keyboard.current;var input=InputSystem.settings.editorInputBehaviorInPlayMode;var bg=InputSystem.settings.backgroundBehavior;Application.runInBackground=true;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;var k=InputSystem.AddDevice<Keyboard>();
try{s.MainMenu();s.ChooseMode(TrainingMode.FireExtinguisher);s.StartSimulation();p.SetCapture(true);foreach(var target in new[]{new Vector3(0,0,-19.05f),new Vector3(0,0,-10.5f),new Vector3(0,0,6.6f),new Vector3(0,0,15.15f),new Vector3(14.2f,0,-.2f)}){double start=Time.realtimeSinceStartupAsDouble;float distance=0;var previous=p.transform.position;bool pathOK=true;while(Vector3.Distance(new Vector3(p.transform.position.x,0,p.transform.position.z),target)>.5f&&Time.realtimeSinceStartupAsDouble-start<35){if(s.Page=="Pause")s.Resume();NavMeshHit h;var path=new NavMeshPath();if(!NavMesh.SamplePosition(p.transform.position,out h,.5f,NavMesh.AllAreas)||!NavMesh.CalculatePath(h.position,target,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete){pathOK=false;break;}var waypoint=path.corners.Skip(1).FirstOrDefault(v=>Vector3.Distance(new Vector3(v.x,0,v.z),new Vector3(p.transform.position.x,0,p.transform.position.z))>.32f);if(waypoint==Vector3.zero)waypoint=target;var delta=waypoint-p.transform.position;delta.y=0;if(delta.sqrMagnitude>.001f){p.transform.rotation=Quaternion.LookRotation(delta);p.view.localRotation=Quaternion.identity;typeof(DesktopPlayerController).GetField("pitch",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(p,0f);}if(Vector3.Distance(p.transform.position,s.evacuation.exitDoor.transform.position)<2.3f)s.evacuation.exitDoor.RequestOpenNearby(p.transform.position);InputSystem.QueueStateEvent(k,new KeyboardState(Key.W,Key.LeftShift));await Task.Delay(35);distance+=Vector3.Distance(previous,p.transform.position);previous=p.transform.position;}InputSystem.QueueStateEvent(k,new KeyboardState());await Task.Delay(100);checks.Add(new{target=target.ToString(),pass=pathOK&&Vector3.Distance(new Vector3(p.transform.position.x,0,p.transform.position.z),target)<.6f,position=p.transform.position.ToString(),seconds=Time.realtimeSinceStartupAsDouble-start,distance});}s.MainMenu();}finally{InputSystem.RemoveDevice(k);if(oldK!=null&&oldK.added)oldK.MakeCurrent();InputSystem.settings.editorInputBehaviorInPlayMode=input;InputSystem.settings.backgroundBehavior=bg;}
var json=Newtonsoft.Json.JsonConvert.SerializeObject(new{scope="Continuous virtual W+Shift movement through CharacterController from main spawn into every additional classroom, then assembly; automatic yaw along NavMesh; no player teleport",checks},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(Path.GetFullPath("../Documentation/SchoolPlayerExploration.json"),json);return json;}}
